using System.Net;
using System.Text.Json;
using Htt.Host.Api.Inventory;
using Htt.Host.Api.MasterData;
using Htt.Infrastructure;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class BinCountTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);
 private static Guid Id(JsonElement x)=>x.GetProperty("id").GetGuid();private static long V(JsonElement x)=>x.GetProperty("version").GetInt64();
 private async Task<(SalesData Data,string One,string Two,Guid Second)> Stock(HttpClient c,decimal qty=10)
 {var d=await Setup(db,c,qty);if(qty>0)await StockValuation.InitializeAsync(db.Owner,db.Company,d.Warehouse,d.Product,qty*10,Code(),DatabaseFixture.Issuer,db.Subject);var one=await Staff(db,"WAREHOUSE",d);var two=await Staff(db,"WAREHOUSE",d);var second=(Guid)(await S("SELECT user_id FROM identity.memberships WHERE company_id=@c AND id=@id",("c",db.Company),("id",two.Membership)))!;return(d,one.Subject,two.Subject,second);}
 private static async Task<JsonElement> Start(HttpClient c,SalesData d,string? key=null)=>await Expect(await Send(c,HttpMethod.Post,"/warehouse/bin-counts",new StockCountInput(d.Warehouse,Code(),"Blind physical count",[d.Product]),key:key),HttpStatusCode.Created);
 private static Task<HttpResponseMessage> Submit(HttpClient c,JsonElement s,decimal qty,string? key=null)=>Send(c,HttpMethod.Post,$"/warehouse/bin-counts/{Id(s)}/submit",new BinCountSubmission(s.GetProperty("lines").EnumerateArray().Select(l=>new BinCountReading(Id(l),qty)).ToArray()),V(s),key);
 private static Task<HttpResponseMessage> Approve(HttpClient c,JsonElement s,IReadOnlyList<BinCountGain>? gains=null,string? key=null)=>Send(c,HttpMethod.Post,$"/accounting/bin-counts/{Id(s)}/approve",new BinCountDecision("Independent review completed",gains),V(s),key);
 private static Task<HttpResponseMessage> Post(HttpClient c,JsonElement s,string? key=null)=>Send(c,HttpMethod.Post,$"/accounting/bin-counts/{Id(s)}/post",new BinCountDecision("Post approved stock and cost"),V(s),key);
 private static Task<HttpResponseMessage> Recount(HttpClient c,JsonElement s,Guid actor)=>Send(c,HttpMethod.Post,$"/accounting/bin-counts/{Id(s)}/recount",new BinCountRecount(actor,"Recheck physical bin variance"),V(s));
 private async Task<JsonElement> Approved(HttpClient admin,HttpClient first,HttpClient second,SalesData d,Guid actor,decimal qty,IReadOnlyList<BinCountGain>? gains=null)
 {var s=await Start(first,d);s=await Expect(await Submit(first,s,qty),HttpStatusCode.OK);s=await Expect(await Recount(admin,s,actor),HttpStatusCode.OK);var blind=await Get(second,$"/warehouse/bin-counts/{Id(s)}");s=await Expect(await Submit(second,blind,qty),HttpStatusCode.OK);return await Expect(await Approve(admin,s,gains),HttpStatusCode.OK);}
 [Theory][InlineData(8,80)][InlineData(12,120)][InlineData(0,0)]public async Task Independent_recount_posts_exact_SKU_and_position_cost(decimal actual,decimal value)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);using var second=api.Authenticated(d.Two);var s=await Approved(c,first,second,d.Data,d.Second,actual);s=await Expect(await Post(c,s),HttpStatusCode.OK);Assert.Equal("POSTED",s.GetProperty("state").GetString());Assert.Equal(actual,await S("SELECT sum(on_hand)FROM inventory.stock_balances WHERE company_id=@c",("c",db.Company)));Assert.Equal(actual,await S("SELECT sum(quantity)FROM inventory.positions WHERE company_id=@c",("c",db.Company)));Assert.Equal(value,await S("SELECT sum(value)FROM inventory.stock_values WHERE company_id=@c",("c",db.Company)));await FinancialReportAssertions.Check(c);}
 [Fact]public async Task Blind_and_legacy_count_views_hide_expected_quantities_costs_and_first_round_from_recounter()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);using var second=api.Authenticated(d.Two);var s=await Start(first,d.Data);Assert.True(s.GetProperty("blind").GetBoolean());Assert.False(s.GetProperty("lines")[0].TryGetProperty("expectedQuantity",out _));Assert.Equal(JsonValueKind.Null,s.GetProperty("financial").ValueKind);var legacy=await Get(first,$"/inventory/stock-counts/{Id(s)}");Assert.True(legacy.GetProperty("blind").GetBoolean());s=await Expect(await Submit(first,s,8),HttpStatusCode.OK);s=await Expect(await Recount(c,s,d.Second),HttpStatusCode.OK);var next=await Get(second,$"/warehouse/bin-counts/{Id(s)}");Assert.Empty(next.GetProperty("lines")[0].GetProperty("readings").EnumerateArray());var review=await Get(c,$"/accounting/bin-counts/{Id(s)}");Assert.Equal(10,D(review.GetProperty("lines")[0].GetProperty("expectedQuantity")));Assert.Equal(100,D(review.GetProperty("financial")[0].GetProperty("snapshotValue")));}
 [Fact]public async Task No_variance_can_be_independently_approved_without_recount_or_journal()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var wh=api.Authenticated(d.One);var s=await Start(wh,d.Data);s=await Expect(await Submit(wh,s,10),HttpStatusCode.OK);s=await Expect(await Approve(c,s),HttpStatusCode.OK);s=await Expect(await Post(c,s),HttpStatusCode.OK);Assert.Equal(0L,await S("SELECT count(*)FROM accounting.posting_batches WHERE company_id=@c AND source_document_id=@id",("c",db.Company),("id",Id(s))));await FinancialReportAssertions.Check(c);}
 [Fact]public async Task Variance_requires_recount_by_different_assigned_counter()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var wh=api.Authenticated(d.One);var s=await Start(wh,d.Data);s=await Expect(await Submit(wh,s,9),HttpStatusCode.OK);await Expect(await Approve(c,s),HttpStatusCode.Conflict);var actor=(Guid)(await S("SELECT id FROM identity.users WHERE subject=@subject",("subject",d.One)))!;await Expect(await Recount(c,s,actor),HttpStatusCode.UnprocessableEntity);await Expect(await Submit(c,s,9),HttpStatusCode.Forbidden);}
 [Fact]public async Task Counter_with_financial_role_still_cannot_self_approve()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);var s=await Start(c,d.Data);s=await Expect(await Submit(c,s,10),HttpStatusCode.OK);await Expect(await Approve(c,s),HttpStatusCode.Forbidden);}
 [Fact]public async Task New_empty_SKU_gain_needs_financial_value_and_can_be_discovered_in_a_bin()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c,0);using var first=api.Authenticated(d.One);using var second=api.Authenticated(d.Two);var s=await Start(first,d.Data);var bin=Id(await Expect(await Send(first,HttpMethod.Post,"/warehouse/bins",new BinInput(d.Data.Warehouse,"A01","New lot shelf")),HttpStatusCode.Created));s=await Expect(await Send(first,HttpMethod.Post,$"/warehouse/bin-counts/{Id(s)}/positions",new BinCountDiscover(d.Data.Product,bin,"FOUND-LOT"),V(s)),HttpStatusCode.OK);BinCountSubmission Input(JsonElement v)=>new(v.GetProperty("lines").EnumerateArray().Select(l=>new BinCountReading(Id(l),l.GetProperty("snapshot").GetProperty("binCode").GetString()=="A01"?2:0)).ToArray());s=await Expect(await Send(first,HttpMethod.Post,$"/warehouse/bin-counts/{Id(s)}/submit",Input(s),V(s)),HttpStatusCode.OK);s=await Expect(await Recount(c,s,d.Second),HttpStatusCode.OK);s=await Expect(await Send(second,HttpMethod.Post,$"/warehouse/bin-counts/{Id(s)}/submit",Input(s),V(s)),HttpStatusCode.OK);await Expect(await Approve(c,s),HttpStatusCode.UnprocessableEntity);s=await Expect(await Approve(c,s,[new(d.Data.Product,25)]),HttpStatusCode.OK);s=await Expect(await Post(c,s),HttpStatusCode.OK);Assert.Equal(25m,await S("SELECT sum(value)FROM inventory.stock_values WHERE company_id=@c",("c",db.Company)));Assert.Equal(2m,await S("SELECT sum(p.quantity)FROM inventory.positions p JOIN inventory.bins b ON b.company_id=p.company_id AND b.id=p.bin_id WHERE p.company_id=@c AND b.code='A01'",("c",db.Company)));await FinancialReportAssertions.Check(c);}
 [Theory][InlineData("move")][InlineData("cost")][InlineData("quantity")]
 public async Task Snapshot_rejects_moves_value_change_or_quantity_ABA(string change)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);using var second=api.Authenticated(d.Two);var s=await Approved(c,first,second,d.Data,d.Second,8);if(change=="move"){var bin=Id(await Expect(await Send(c,HttpMethod.Post,"/warehouse/bins",new BinInput(d.Data.Warehouse,"B01","Moved")),HttpStatusCode.Created));await Expect(await Send(c,HttpMethod.Post,"/warehouse/location-moves",new PositionMoveInput(s.GetProperty("lines")[0].GetProperty("positionId").GetGuid(),bin,"MOVED",1,Code(),"Moved after snapshot")),HttpStatusCode.Created);}if(change=="cost")await S("UPDATE inventory.stock_values SET value=value WHERE company_id=@c",("c",db.Company));if(change=="quantity")await S("UPDATE inventory.stock_balances SET revision=revision WHERE company_id=@c",("c",db.Company));await Expect(await Post(c,s),HttpStatusCode.Conflict);Assert.Equal("APPROVED",(await Get(c,$"/accounting/bin-counts/{Id(s)}")).GetProperty("state").GetString());}
 [Theory][InlineData("SALES")][InlineData("OFFICE")][InlineData("PROCUREMENT")]
 public async Task Operational_roles_cannot_start_review_or_post_counts(string role)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);var staff=await Staff(db,role,d.Data);using var limited=api.Authenticated(staff.Subject);await Expect(await Send(limited,HttpMethod.Post,"/warehouse/bin-counts",new StockCountInput(d.Data.Warehouse,Code(),"Denied",[d.Data.Product])),HttpStatusCode.Forbidden);}
 [Fact]public async Task Warehouse_assignment_and_company_boundaries_are_enforced()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);var s=await Start(first,d.Data);var staff=await Staff(db,"WAREHOUSE");using var outside=api.Authenticated(staff.Subject);await Expect(await Send(outside,HttpMethod.Get,$"/warehouse/bin-counts/{Id(s)}"),HttpStatusCode.Forbidden);using var other=api.Authenticated(company:db.OtherCompany);await Expect(await Send(other,HttpMethod.Get,$"/accounting/bin-counts/{Id(s)}"),HttpStatusCode.NotFound);}
 [Fact]public async Task Old_submit_and_post_routes_cannot_skip_bin_review()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);var s=await Start(first,d.Data);await Expect(await Send(first,HttpMethod.Post,$"/inventory/stock-counts/{Id(s)}/submit",new StockCountSubmission([new(d.Data.Product,10)]),1),HttpStatusCode.Forbidden);await Expect(await Send(c,HttpMethod.Post,$"/inventory/stock-counts/{Id(s)}/post",version:1),HttpStatusCode.Conflict);}
 [Theory][InlineData(true)][InlineData(false)]public async Task Concurrent_same_version_post_has_one_economic_effect(bool sameKey)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);using var second=api.Authenticated(d.Two);var s=await Approved(c,first,second,d.Data,d.Second,8);var key=Code();var all=await Task.WhenAll(Post(c,s,key),Post(c,s,sameKey?key:Code()));Assert.Equal(sameKey?2:1,all.Count(r=>r.StatusCode==HttpStatusCode.OK));if(!sameKey)Assert.Single(all,r=>r.StatusCode==HttpStatusCode.Conflict);Assert.Equal(1L,await S("SELECT count(*)FROM inventory.operations WHERE company_id=@c AND id=@id",("c",db.Company),("id",Id(s))));await FinancialReportAssertions.Check(c);}
 [Fact]public async Task Idempotent_submission_replays_but_changed_actual_conflicts()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);var s=await Start(first,d.Data);var key=Code();var a=await Expect(await Submit(first,s,10,key),HttpStatusCode.OK);Assert.True(JsonElement.DeepEquals(a,await Expect(await Submit(first,s,10,key),HttpStatusCode.OK)));await Expect(await Submit(first,s,9,key),HttpStatusCode.Conflict);}
 [Fact]public async Task Financial_review_and_post_are_separate_from_warehouse_capture()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);using var second=api.Authenticated(d.Two);var fin=await Staff(db,"FINANCE");using var finance=api.Authenticated(fin.Subject);var s=await Start(first,d.Data);s=await Expect(await Submit(first,s,10),HttpStatusCode.OK);await Expect(await Approve(first,s),HttpStatusCode.Forbidden);s=await Expect(await Approve(finance,s),HttpStatusCode.OK);await Expect(await Post(finance,s),HttpStatusCode.OK);await FinancialReportAssertions.Check(c);}
 [Fact]public async Task Creator_can_cancel_without_financial_effects()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);var s=await Start(first,d.Data);s=await Expect(await Send(first,HttpMethod.Post,$"/warehouse/bin-counts/{Id(s)}/cancel",new BinCountDecision("Stock moved; restart"),V(s)),HttpStatusCode.OK);Assert.Equal("CANCELLED",s.GetProperty("state").GetString());await Expect(await Submit(first,s,10),HttpStatusCode.Conflict);}

 [Fact]public async Task Privileged_counter_is_blind_and_cannot_use_financial_view()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);var s=await Start(c,d.Data);Assert.True(s.GetProperty("blind").GetBoolean());await Expect(await Send(c,HttpMethod.Get,$"/accounting/bin-counts/{Id(s)}"),HttpStatusCode.Forbidden);}
 [Theory][InlineData("submit")][InlineData("approve")][InlineData("post")]
 public async Task Audit_failure_rolls_back_action_and_same_key_retries(string action)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);var s=await Start(first,d.Data);if(action!="submit")s=await Expect(await Submit(first,s,10),HttpStatusCode.OK);if(action=="post")s=await Expect(await Approve(c,s),HttpStatusCode.OK);var key=Code();var v=V(s);Task<HttpResponseMessage> Run()=>action switch{"submit"=>Submit(first,s,10,key),"approve"=>Approve(c,s,key:key),_=>Post(c,s,key)};await S($"CREATE FUNCTION inventory.test_w06_fail()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'AND NEW.action='inventory.bin_count_{action}'THEN RAISE EXCEPTION 'Injected' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_w06_fail BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION inventory.test_w06_fail()");try{await Expect(await Run(),HttpStatusCode.UnprocessableEntity);Assert.Equal(v,V(await Get(first,$"/warehouse/bin-counts/{Id(s)}")));Assert.Equal(0L,await S("SELECT count(*)FROM inventory.operations WHERE company_id=@c AND id=@id",("c",db.Company),("id",Id(s))));}finally{await S("DROP TRIGGER test_w06_fail ON platform.audit_events;DROP FUNCTION inventory.test_w06_fail()");}await Expect(await Run(),HttpStatusCode.OK);}
 [Fact]public async Task Revoked_capture_cannot_replay_cached_response()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);var s=await Start(first,d.Data);var key=Code();await Expect(await Submit(first,s,10,key),HttpStatusCode.OK);await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='inventory.bin_counts.capture'",("c",db.Company));await Expect(await Submit(first,s,10,key),HttpStatusCode.Forbidden);}
 [Theory][InlineData(true)][InlineData(false)]public async Task Missing_or_null_quantity_is_rejected_without_changes(bool missing)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);var s=await Start(first,d.Data);await Expect(await Send(first,HttpMethod.Post,$"/warehouse/bin-counts/{Id(s)}/submit",new BinCountSubmission(missing?[]:[new(Id(s.GetProperty("lines")[0]),null)]),V(s)),HttpStatusCode.UnprocessableEntity);Assert.Equal("OPEN",(await Get(first,$"/warehouse/bin-counts/{Id(s)}")).GetProperty("state").GetString());}
 [Fact]public async Task Bin_redistribution_requires_recount_but_does_not_post_SKU_or_GL_changes()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);using var second=api.Authenticated(d.Two);var bin=Id(await Expect(await Send(c,HttpMethod.Post,"/warehouse/bins",new BinInput(d.Data.Warehouse,"R01","Reallocate")),HttpStatusCode.Created));var s=await Start(first,d.Data);s=await Expect(await Send(first,HttpMethod.Post,$"/warehouse/bin-counts/{Id(s)}/positions",new BinCountDiscover(d.Data.Product,bin,"NEW"),V(s)),HttpStatusCode.OK);BinCountSubmission Input(JsonElement v)=>new(v.GetProperty("lines").EnumerateArray().Select(l=>new BinCountReading(Id(l),l.GetProperty("snapshot").GetProperty("binCode").GetString()=="R01"?4:6)).ToArray());s=await Expect(await Send(first,HttpMethod.Post,$"/warehouse/bin-counts/{Id(s)}/submit",Input(s),V(s)),HttpStatusCode.OK);await Expect(await Approve(c,s),HttpStatusCode.Conflict);s=await Expect(await Recount(c,s,d.Second),HttpStatusCode.OK);s=await Expect(await Send(second,HttpMethod.Post,$"/warehouse/bin-counts/{Id(s)}/submit",Input(s),V(s)),HttpStatusCode.OK);s=await Expect(await Approve(c,s),HttpStatusCode.OK);s=await Expect(await Post(c,s),HttpStatusCode.OK);Assert.Equal(4m,await S("SELECT sum(p.quantity)FROM inventory.positions p JOIN inventory.bins b ON b.company_id=p.company_id AND b.id=p.bin_id WHERE p.company_id=@c AND b.code='R01'",("c",db.Company)));Assert.Equal(100m,await S("SELECT sum(value)FROM inventory.stock_values WHERE company_id=@c",("c",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM accounting.posting_batches WHERE company_id=@c AND source_document_id=@id",("c",db.Company),("id",Id(s))));await FinancialReportAssertions.Check(c);}

 [Fact]public async Task Count_cannot_post_after_accounting_period_closes()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);using var first=api.Authenticated(d.One);using var second=api.Authenticated(d.Two);var s=await Approved(c,first,second,d.Data,d.Second,8);await S("UPDATE accounting.periods SET state='CLOSED'WHERE company_id=@c AND starts_on<=current_date AND ends_on>current_date",("c",db.Company));await Expect(await Post(c,s),HttpStatusCode.UnprocessableEntity);Assert.Equal(100m,await S("SELECT sum(value)FROM inventory.stock_values WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Reserved_stock_cannot_be_removed_by_approved_physical_loss()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Stock(c);var quote=await Submitted(c,d.Data.Draft(1));await Expect(await SalesFlowSupport.Approve(c,quote.Id,quote.Version),HttpStatusCode.Created);using var first=api.Authenticated(d.One);using var second=api.Authenticated(d.Two);var s=await Start(first,d.Data);s=await Expect(await Submit(first,s,1),HttpStatusCode.OK);s=await Expect(await Recount(c,s,d.Second),HttpStatusCode.OK);s=await Expect(await Submit(second,s,1),HttpStatusCode.OK);await Expect(await Approve(c,s),HttpStatusCode.UnprocessableEntity);Assert.Equal(2.2m,await S("SELECT sum(reserved)FROM inventory.stock_balances WHERE company_id=@c",("c",db.Company)));}
}
